"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[4992],{56461:e=>{e.exports=JSON.parse('{"functions":[{"name":"track","desc":"Joins the election and starts tracking leadership. The search runs on a\\nbackground task registered into `scope`; cleaning up the scope stops\\ntracking and, if this peer is the leader, hands leadership over first.","params":[{"name":"scope","desc":"Cleanup scope (see doCleanup) owning the tracker\'s connections and task.","lua_type":"{ unknown }"},{"name":"interposer","desc":"A logged-on Interposer session to elect over.","lua_type":"InterposerApi"}],"returns":[{"desc":"","lua_type":"LeaderApi"}],"function_type":"static","source":{"line":71,"path":"plugin/leader/init.luau"}}],"properties":[],"types":[{"name":"LeaderApi","desc":"","fields":[{"name":"leader","lua_type":"() -> Peer?","desc":"Current leader, or `nil` while undecided."},{"name":"selfIsLeader","lua_type":"() -> boolean?","desc":"Whether this peer leads; `nil` while undecided."},{"name":"onLeaderChanged","lua_type":"Connect<Peer?>","desc":"Fires whenever a different leader takes over."}],"source":{"line":37,"path":"plugin/leader/init.luau"}}],"name":"Leader","desc":"Elects a single leader among plugin instances running in the same Studio\\nsession, over an [Interposer] peer network. Used when several copies of\\na plugin coexist (local dev rig plus installed copy) and exactly one\\nshould own a shared resource such as a toolbar.\\n\\nElection: each peer first asks the others `whoIsLeader`; a peer that\\nclaims itself is believed. If nobody knows, only the peer with the\\nlexicographically lowest id self-elects (ids are GUIDs, so every peer\\nagrees), which avoids the co-arrival race where all peers elect\\nthemselves in the same tick. A leader that shuts down hands leadership\\nto another peer on the way out.","source":{"line":29,"path":"plugin/leader/init.luau"}}')}}]);